import{stopClock,renderClock}from"../components/clock/clock.js";let isNavigating=false;function getSettings(){try{const stored=localStorage.getItem("settings");return stored?JSON.parse(stored):{};}catch{return{};}}
export function navigateTo(url,options={}){if(!url||url.trim()===""||url.startsWith("javascript:"))return;const settings=getSettings();const shouldOpenInNewTab=options.newTab!==undefined?Boolean(options.newTab):Boolean(settings.openInNewTab);if(url.startsWith("chrome://")||url.startsWith("edge://")||url.startsWith("about:")){if(typeof chrome!=="undefined"&&chrome.tabs){if(shouldOpenInNewTab&&chrome.tabs.create){chrome.tabs.create({url:url});}else if(chrome.tabs.update){chrome.tabs.update({url:url});}else{window.open(url,"_blank");}
return;}}
if(shouldOpenInNewTab){if(typeof chrome!=="undefined"&&chrome.tabs&&chrome.tabs.create){chrome.tabs.create({url:url});}else{window.open(url,"_blank");}
return;}
if(isNavigating)return;isNavigating=true;stopClock();if(options.immediate){window.location.href=url;return;}
document.body.classList.add("navigating");setTimeout(()=>{window.location.href=url;},90);}
export function initNavigationHelper(){document.addEventListener("click",(e)=>{if(e.button!==0)return;if(e.ctrlKey||e.metaKey||e.shiftKey)return;const anchor=e.target.closest("a[href]");if(!anchor)return;const href=anchor.getAttribute("href");if(!href||href==="#"||href.startsWith("javascript:"))return;if(anchor.target==="_blank"){return;}
e.preventDefault();navigateTo(anchor.href);},true);window.addEventListener("pageshow",()=>{isNavigating=false;document.body.classList.remove("navigating");const settings=getSettings();if(settings.clock!==false){renderClock();}});window.addEventListener("pagehide",()=>{stopClock();});}